(function(){try{var e=typeof window<"u"?window:typeof global<"u"?global:typeof globalThis<"u"?globalThis:typeof self<"u"?self:{},r=new e.Error().stack;r&&(e._sentryDebugIds=e._sentryDebugIds||{},e._sentryDebugIds[r]="b8e32a0f-92f9-4378-bd79-93c4aff67e38",e._sentryDebugIdIdentifier="sentry-dbid-b8e32a0f-92f9-4378-bd79-93c4aff67e38")}catch{}})();var t="Fellesskapets retningslinjer for atferd",l={p1:"Vi er alle glade i musikk! Som i ethvert fellesskap har vi retningslinjer for god oppførsel for å bevare harmonien og den gode stemningen, og for at alle skal trives her. La oss sammen bygge et vennlig miljø som inspirerer oss til å skape musikk."},n={p1:"Prinsipper for samspill:",p2:"Respekt",p3:"Fellesskap",p4:"Likeverd"},s={p1:"Forventet atferd:",p2:"Behandle alle medlemmer med respekt.",p3:"Konstruktive tilbakemeldinger er velkomne.",p4:"Her handler alt om musikk, så la oss holde kommentarer og innhold utelukkende relatert til musikk.",p5:"Behandle andre slik du selv ønsker å bli behandlet."},a={p1:"Uakseptabel atferd (vi kan slette kontoen din uten forvarsel):",p2:"Å behandle medskapere respektløst eller støtende.",p3:"Spam.",p4:"Å dele seksuelt innhold.",p5:"Å skrive kommentarer som har til hensikt å nedverdige, fornærme eller irritere ethvert medlem av fellesskapet."},i={p1:"Offentlige tiltak:"},d={p1:"Grunner til umiddelbar utestengelse:",p2:"Dele seksuelt innhold av noe slag (bilder, kommentarer osv.).",p3:"Dele innhold eller komme med kommentarer som oppfordrer til vold, rasisme, fremmedfiendtlighet, homofobi, sexisme osv.",p4:"Spamme andre."},o={p1:"Andre former for uakseptabel atferd:",p2:"Å fornærme eller publisere nedsettende kommentarer om medlemmer av fellesskapet:",p3:"Første gang: Vi deaktiverer muligheten til å kommentere inntil videre.",p4:"Andre gang: Vi vil permanent deaktivere muligheten til å kommentere eller slette kontoen din.",p5:"Spam mot brukerstøtte:",p6:"Brukerstøtteteamet vårt hjelper deg gjerne, så lenge du henvender deg på en respektfull måte og kun om plattformen vår. Respektløs eller spammende opptreden er ikke velkommen og kan føre til at kontoen din blir slettet."},m={p1:"Hva er en respektløs kommentar?",p2:"Denne typen kommentar er som regel irrelevant, upassende, skadelig eller bare irriterende. Den er ikke skrevet i god hensikt og er ment å få den andre til å føle seg dårlig eller ydmyket.",p3:"Hvis du er usikker på om kommentaren din er respektløs, la være å publisere den og finn en respektfull og saklig måte å uttrykke deg på."},p={title:t,s1:l,s2:n,s3:s,s4:a,s5:i,s6:d,s7:o,s8:m};export{p as default,l as s1,n as s2,s as s3,a as s4,i as s5,d as s6,o as s7,m as s8,t as title};

